fn main() {
    tauri_build::try_build(
        tauri_build::Attributes::new().app_manifest(
            tauri_build::AppManifest::new()
                // Remote-origin ACL: the release webview loads the SPA from the
                // server (http://127.0.0.1), so custom commands are only reachable
                // after autogenerated allow-* permissions are granted in the
                // capability file.
                .commands(&["close_action", "open_logs_window"]),
        ),
    )
    .expect("failed to run tauri-build");
}
